317		\begin{equation}\label{eq:am-i-hermitian}
318			\mathcal O_A \mathcal O_B \ot \sigma^Z \sigma^X
319			= - \mathcal O_A \mathcal O_B \ot \sigma^X \sigma^Z
320			= \mathcal O_B \mathcal O_A \ot \sigma^X \sigma^Z
