  5	\subsection{The qudit pauli group}
  6	In this subsection, we formally introduce the Pauli group. We state definitions and prove properties for the Pauli group mod $d$. However, we will later only utilize such properties for the Pauli group mod $2$. As mentioned earlier, a manuscript by Joel Wallman, to appear shortly after this one, shows that there does not exist any pseudotelepathy LCS game mod $d$, for $d\neq 2$, whose ideal strategy consists of products of Pauli operators.
  7	\begin{definition}\label{definition:n-qudit-pauli-group}
  8		The $n$-qudit Pauli group of local dimension $d$ is denoted $\m P_d^{\otimes n} := \braket{S:R}_{\Z_d}$ and presented with generators and relations
  9		\begin{align}
 10			S = \set{x_i,z_i\;i\leq n}
 11			&&
 12			R = \set{J\1[x_i,z_i], [x_i,x_j], [z_i,z_j], [x_i,z_j]\;i \neq j \leq n}
 13		\end{align}
 14	\end{definition}
 15	
 16	We aim to show that the Pauli group is suitable for applying the results from Section \ref{sec:self-testing}. 
 17	
 18	\begin{definition}
 19	\label{def:representations-pauli-group}
 20		We now define maps $\tau_l^{(n)}: \m P_d^{\otimes n} \to U(\C^{d})^{\otimes n}$ as 
 21		\begin{align}
 22		\tau_l^{(n)}(J) &= \w_d^l I
 23		,
 24		\\\tau_l^{(n)}(x_i) &= \underbrace{I\otimes \cdots I}_{i-1} \otimes X^l \otimes \underbrace{I \otimes\cdots \otimes I}_{n-i}
 25		,
 26		\\\tau_l^{(n)}(z_i) &= \underbrace{I\otimes \cdots I}_{i-1} \otimes Z \otimes \underbrace{I \otimes\cdots \otimes I}_{n-i}.
 27		\end{align}
 28	\end{definition}
 29	\begin{lemma}
 30	\label{lemma:representations-pauli-group}
 31		The $\set{\tau_l^{(n)}\;l\in \Z_d\minus\set0}$ are $d-1$ inequivalent representations of dimension $d^n$. 
 32	\end{lemma}
 33	\begin{proof}
 34		To see that they are representations, it suffices to check the commutation and anticommutation relations. To see that they are inequivalent, see that their characters differ at $J$, since $\Tr\tau_l^{(n)}(J) = \w_d^ld^n$. 
 35	\end{proof}
 36	
 37	\begin{prop}\label{prop:representations-pauli-group}
 38		$\m P_d^{\otimes n}$ group-tests $\tau_1^{(n)}$ in the sense of Definition \ref{definition:group-test}.
 39	\end{prop}
 40	
 41	To prove this, we first establish the following lemma, which will let us count the elements of $\pauli$.
 42	
 43	\begin{lemma}
 44	\label{lemma:canonical-form}
 45		There is a canonical form $\can: \m P_d^{\otimes n} \to \m F(S)$ which sends each element to a string of the form
 46		\begin{equation}
 47		 	J^{a_1}\prod_{i=1}^nx_i^{a_{2i}}z_i^{a_{2i+1}}, a_i\in \Z_d.
 48		 \end{equation}
 49	\end{lemma}
 50	\begin{proof}
 51		First, we see that each element can be written this way. Start with an arbitrary word representing the element and apply the commutation and anticommutation relations to get the $x_i$ and $z_i$ in order. Finish by commuting all of the $J$s to the front and applying the relations $s^d = 1$ to get all of the exponents to lie in $\Z_d$. 
 52	
 53		Next, we see that different words represent different group elements. Suppose that 
 54	 	\begin{equation}\label{eq:canonical-form}
 55	 		J^{a_1}\prod_{i=1}^nx_i^{a_{2i}}z_i^{a_{2i+1}} = J^{b_1}\prod_{i=1}^nx_i^{b_{2i}}z_i^{b_{2i+1}}.
 56	 	\end{equation}
 57	 	Then by various applications of the (twisted) commutation relations, we have
 58	 	\begin{equation}\label{eq:canonical-form-uniqueness}
 59	 		J^{c_1} = \prod_{i=1}^nx_i^{a_{2i} - b_{2i}}z_i^{a_{2i+1}-b_{2i+1}}
 60	 	\end{equation}
 61	 	for some $c_1 \in \Z_d$. The left hand side is always central, but the right hand side is central only if $a_i = b_i$ for all $i\in [2,2n+1]$. 
 62	 	(Suppose for example that $a_3 - b_3 \neq 0$, so that the power of $z_1$ is nonzero. Then the right hand side fails to commute with $x_1$.) 
 63	 	In this case, we can see that in fact $c_1 = a_1 - b_1$, so equation \eqref{eq:canonical-form-uniqueness} holds only if $J^{c_1} = 1$ in the group. 
 64	 	 But Proposition \ref{lemma:representations-pauli-group} gives us a representation in which $J$ and $1$ are represented by distinct matrices. Therefore, equation \eqref{eq:canonical-form-uniqueness} holds only when $a_i = b_i$ for all $i$.
 65	\end{proof}
 66	
 67	Thanks to the canonical form, we can easily compute the size of $\m P_d^{\otimes n}$.
 68	\begin{cor}
 69		$\m P_d^{\otimes n}$ has $d^{2n+1}$ elements.
 70	\end{cor}
 71	\begin{proof}[Proof of Proposition \ref{prop:representations-pauli-group}]
 72		We'll check that $\m P_d^{\otimes n}$ has exactly $d-1$ irreducible representations of dimension $d^{n}$, each sending $J$ to a different nontrivial $d\th$ root of unity. All other irreducible representations are $1$-dimensional and send $J$ to $1$. 
 73	
 74		We'll complete the character table of $\pauli$. Now that we know the size of the group, we can check via Fact \ref{fact:irreducibility-criterion} that the representations of Lemma \ref{lemma:representations-pauli-group} are irreducible. 
 75	
 76		Next, we notice that the commutator subgroup $[\m P_d^{\otimes n},\m P_d^{\otimes n}]$ is equal to $\braket J$, the cyclic subgroup generated by $J$. This has order $d$, so by Fact \ref{fact:1-dim-irreps}, there are $d^{2n}$ irreps of dimension $1$ which send $J$ to $1$. Now we add the squares of the dimensions of our irreps and see that they saturate equation \eqref{eq:character-dimension}.
 77		\begin{equation}
 78			\abs\pauli = d^{2n+1} = (d-1)\cdot (d^n)^2 + (d^{2n})\cdot(1)^2 = \sum_\s (\dim \s)^2.
 79		\end{equation}
 80		Therefore, we've found all irreducible representations of $\pauli$. 
 81	\end{proof}
