  3	In this section, we introduce our main robust self-testing theorem for linear constraint system games with solution groups of a certain form. In \S \ref{subsection:exact-self-testing}, to ease understanding, we start by stating and proving an exact version of the theorem. In \S \ref{subsection:state-dependent-distance} through \S \ref{subsection:quant-stabilizer-state-bounds}, we introduce the necessary tools to prove an approximate version of the self-testing theorem. \S \ref{subsection:state-dependent-distance} introduces the state-dependent distance and some of its properties. \S \ref{subsection:stability-lemma} proves a stability lemma for representations of finite groups, which allows us to deduce that the action of a strategy winning with high probability is close to the action of a representation of the solution group.  \S \ref{subsection:quant-van-kampen} presents a quantitative version of the van Kampen Lemma from Section \S \ref{subsection:van-kampen-diagrams}, which is key in bounding the robustness of the main theorem. \S \ref{subsection:quant-stabilizer-state-bounds} shows that if a joint state is approximately stabilized by the action of the Pauli group on two tensor factors, then it is close to the maximally entangled state on the two tensor factors. In \S \ref{subsection:robust-self-testing} we combine these tools to prove our robust self-testing theorem. 
  4	 
  5	\subsection{Exact self-testing}
  6	\label{subsection:exact-self-testing}
  7	
  8	Throughout, let $\LCS(\mathbf H, l, \Z_d), \mathbf H = (V,E,H)$ be an LCS game with solution group $\G$.
  9	
 10	\begin{thm}[Rigid self-testing of observables]\label{thm:rigid-self-testing-observables}
 11	Suppose $\G$ is finite and all of its irreducible representations with $J\mapsto \w_d I$ are equivalent to a fixed irrep $\s:\G\to U(\C^d)$. Suppose $\set{A_e^{(v)}}, \set{B_e}, \rho\in \m L(\m H_A\otimes \m H_B)$ is a perfect strategy presented via observables for the game. 
 12	Then there are local isometries $V_A, V_B$ such that
 13		\begin{itemize}
 14			\item for all $e,v$, $V_AA_e^{(v)}V_A^\dagger = \s(e)\otimes I \oplus \hat A^{(v)}_e$, where $\hat A^{(v)}_e V_A\rho V_A^\dagger = 0$, and 
 15			\item for all $e$ $V_BB_eV_B^\dagger =\bar{\s(e)}\otimes I \oplus \hat B_e$, where $\hat B_e V_B\rho V_B^\dagger = 0$.
 16		\end{itemize}
 17	\end{thm}
 18	Awkwardly, we must pick a basis to take the complex conjugate in. Fortunately, we only care about our operators up to isometry. So to make sense of the theorem statement, we pick the basis for complex conjugation first, and then the isometry $V_B$ depends on this choice.
 19	 We break the proof into two lemmas.
 20	\begin{lemma}\label{lem:unique-operator-solution}
 21		Suppose $\G$ is finite and all of its irreducible representations with $J\mapsto \w_dI$ are equivalent to a fixed irrep $\s:\G\to U(\C^d)$. Then every operator solution is equivalent to $\s\otimes I$ and every conjugate operator solution is equivalent to $\bar{\s}\otimes I$, where the complex conjugate can be taken in any basis. 
 22	\end{lemma}
 23	
 24	\begin{lemma}[Adapted from Lemma 8, \cite{cleve2016perfect}]\label{lemma:CLS}
 25	Suppose $\set{A_e^{(v)}}, \set{B_e}, \rho\in \m L(\m H_A\otimes \m H_B)$ is a perfect strategy presented via observables for the game. 
 26		Then, there are orthogonal projections $P_A, P_B$ such that 
 27		\begin{enumerate}
 28		\item $(P_A\otimes P_B)\rho(P_A\otimes P_B) = \rho$;
 29		\item for each $e$, $P_AA_e^{(v)}P_A = P_AA_e^{(v')}P_A$, provided that $H(v,e) \neq 0 \neq H(v',e)$ (we now write $P_AA_eP_A$ without ambiguity);
 30		\item the map $\s_A:\G\to \ran P_A$ generated by $e\mapsto P_AA_eP_A$ (and $j \mapsto \w_dI$) is an operator solution;
 31		\item the map $\s_B:\G\to \ran P_B$ generated by $e\mapsto P_BB_eP_B$ (and $j \mapsto \bar{\w_d}I$) is a conjugate operator solution.
 32		\end{enumerate}
 33	\end{lemma}
 34	
 35	\begin{proof}[Proof of Theorem \ref{thm:rigid-self-testing-observables}, assuming the lemmas]
 36	
 37		Take the maps $\s_A$ and $\s_B$ from Lemma \ref{lemma:CLS}; note that their ranges are the subspaces determined by $P_A, P_B$. From Lemma \ref{lem:unique-operator-solution} we get partial isometries $W_A$, $W_B$ such that $W_A\s_A(e)W_A^\dagger = \s(e)\otimes I$ and $W_B\s_B(e)W_B^\dagger = \bar{\s(e)}\otimes I$. To complete the proof, let $V_A$ and $V_B$ be any isometric extensions of $W_A$ and $W_B$, and set 
 38		$\hat A_e^{(v)} = V_A(I-P_A)A_e^{(v)}(I-P_A)V_A^\dagger, \hat B_e = V_B(I-P_B)B_e(I-P_B)V_B^\dagger$. Checking that these operators satisfy the equations in the theorem is a simple computation. 
 39	\end{proof}
