 49	\begin{proof}[Proof of Lemma \ref{lemma:CLS}]
 50		This is essentially the same proof as given in \cite{cleve2016perfect} (their treatment is a bit more complicated since they wish to cover the infinite-dimensional case).
 51	
 52		Let $\m A$ be the set of finite products of unitaries from $\set{A_e^{(v)}}$, and similarly let $\m B$ be the set of finite products of unitaries from $\set{B_e}$. 
 53		Let $\rho_A = \Tr_B \rho$ and $\rho_B = \Tr_A\rho$. Define 
 54		\begin{equation}
 55			\hat{\m H_A} = \supp\rho_A\text{, and }
 56			\hat{\m H_B} = \supp\rho_B\text,
 57		\end{equation}
 58		and let $P_A$ and $P_B$ be the projectors onto these spaces. Notice that $(P_A\otimes P_B) \rho (P_A\otimes P_B) = \rho$. From the consistency criterion \eqref{eq:exact-win-criterion-con}, we have
 59		\begin{equation}\label{eq:CLS-conjugate}
 60			1 	= \Tr_\rho A_e^{(v)}\otimes B_e,\text{ so } A_e^{(v)}\ket\phi = B_e^\dagger\ket\phi\text{ for }\ket\phi\in\supp\rho.
 61		\end{equation}
 62		Let $A\in \m A$ be arbitrary. Then, the above implies that there is $B\in \m B$ be such that $(A\otimes I) \rho (A^\dagger\otimes I) = (I\otimes B^\dagger)\rho(I\otimes B)$. We compute
 63		\begin{align}
 64			A\rho_AA^\dagger
 65			= \Tr_B (A\otimes I)\rho(A^\dagger\otimes I)
 66			= \Tr_B (I\otimes B^\dagger)\rho(I\otimes B)
 67			= \Tr_B \rho
 68			=\rho_A,
 69		\end{align}
 70		from which we conclude that $\m A$ fixes $\hat{\m H_A}$. This implies that $(PA_1P)(PA_2P) = PA_1A_2P$ for $A_1,A_2\in \m A$. 
 71		Next, we compute
 72		\begin{equation}
 73			1 = \Tr_\rho A_e^{(v)}(A_e^{(v')})^\dagger \otimes I
 74			= \Tr_{\rho_A} A_e^{(v)}(A_e^{(v')})^\dagger,
 75		\end{equation}
 76		from which we conclude that $P_AA_e^{(v)}P_A=P_AA_e^{(v')}P_A$. We now write $P_AA_eP_A$ without ambiguity. Finally, we compute
 77		\begin{align}
 78			1 = \Tr_\rho w_d^{-l(v)}\prod_{e:H(v,e)\neq 0} A_e\otimes I = \Tr_{\rho_A} w_p^{-l(v)}\prod_{e:H(v,e)\neq 0} A_e\otimes I,
 79		\end{align}
 80		from which we conclude that the map $e\mapsto P_AA_eP_A$ is an operator solution. The same argument shows that $e\mapsto P_BB_eP_B$ is a conjugate operator solution. (The conjugation comes from equation \eqref{eq:CLS-conjugate}.)
 81	
 82	\end{proof}
