 86	\subsection{State-dependent distance}\label{subsection:state-dependent-distance}
 87	We now begin to collect the necessary tools to generalize the previous subsection to the approximate case. To start, we need a convenient calculus for manipulating our notion of state-dependent distance. Recall the definition of $\drho\rho\cdot\cdot$ as 
 88	\begin{equation}
 89	\drho{\rho}{X}{Y} = \sqrt{\Tr_\rho(X-Y)^\dagger(X-Y)}
 90	\end{equation} 
 91	We use the same notation as the Kullback-–Leibler divergence despite the fact that our $\drho\rho\cdot\cdot$ is symmetric in its arguments. We do this because we will write complicated expressions in the place of $X$ and $Y$; the notation becomes harder to parse if the symbol $\|$ is replaced by a comma.
 92	Notice that if $\rho_{AB}$ is the maximally entangled pure state, then $\drho{\rho_{AB}}{X\otimes I_B}{Y\otimes I_B}$ is exactly the usual $2$-norm distance $\norm{X-Y}_2$. Much like the fidelity of quantum states, the squared distance $\drho\rho\cdot\cdot^2$ is often more natural than the distance. We collect computationally useful properties of $\drho\rho\cdot\cdot$ in the following lemma.
 93	
 94	\begin{lemma}\label{lemma:state-dependent-distance}
 95		Let $\m H = \m H_A\otimes \m H_B$ be a Hilbert space. Let $U,U_i$ be unitary operators on $\m H$. Let $Z,Z_i$ be arbitrary operators on $\m H$. Similarly, let $A_i, B_i$ be unitary operators on $\m H_A, \m H_B$ respectively. Let $X_i, Y_i$ be arbitrary operators on $\m H_A, \m H_B$, respectively.
 96		Let $\rho$ be a state on $\m H_A\otimes \m H_B$. Let $V: \m H\to \m H'$ be an isometry and $U'$ a unitary operator on $\m H'$. Then
 97		\begin{enumerate} [(a)]
 98			\item 
 99			\label{item:state-dependent-distance-square} 
100			$\drho{\rho}{U}{I}^2 =2 - 2\Re\Tr_\rho U$. More generally, $\drho{\rho} ZI = 1 + \Tr_\rho Z\dagg Z - 2\Re\Tr_\rho Z$.
101			\item
102			\label{item:state-dependent-distance-inverse} 
103			$\drho{\rho}{UZ}{I} = \drho{\rho}{Z}{U^\dagger}$. In particular, $\drho{\rho}{U}{I}=\drho{\rho}{U^\dagger}{I}$.
104			\item\label{item:state-dependent-distance-triangle}
105			$\drho{\rho}{Z_1}{Z_3} \leq \drho{\rho}{Z_1}{Z_2} + \drho{\rho}{Z_2}{Z_3}$.
106			\item\label{item:state-dependent-distance-right-multiplication} $\drho{\rho}{ZU_2}{U_3} \leq \drho{\rho}{Z}{I} + \drho{\rho}{U_2}{U_3}$. If $U_2$ commutes with $U_3$ (in particular if $U_3 = I$), then also $\drho{\rho}{U_1U_2}{U_3} \leq \drho{\rho}{U_2}{I} + \drho{\rho}{U_1}{U_3}$.
107			\item\label{item:state-dependent-distance-chaining} $\drho{\rho}{\prod_{i}{A_i\otimes I_B}}{\prod_{i}I_A \otimes B_i} \leq \sum_i \drho{\rho}{A_i\otimes I_B}{ I_A\otimes B_i}$.
108			\item\label{item:state-dependent-distance-conjugation} If $\drho{\rho}{I_A\otimes WB}{I} \leq \nu$ and $\drho{\rho}{A\otimes B}{I}\leq \eta$, then \mbox{$\drho{\rho}{I_A\otimes BW}{I}\leq \nu + 2\eta$.}
109			\item\label{item:state-dependent-distance-jensen}
110			$\drho{\rho}{\E{i}{ U_i}} {I} \leq \E{i}\drho{\rho}{U_i}{ I}$.
111			\item \label{item:state-dependent-distance-partial-trace}
112			$\drho{\rho}{A\otimes I_B}{I_{AB}} = \drho{\rho_A}{A}{I_A}$, where $\rho_A = \Tr_B \rho$.
113			\item \label{item:state-dependent-distance-isometry}
114			$\drho{\rho}{Z_1}{Z_2} = \drho{V\rho V^\dagger}{VZ_1V^\dagger}{VZ_2V^\dagger}$. 
115			\item\label{item:state-dependent-distance-projection-is-identity} 
116			If $P$ is a projection such that $P\rho = P$, then $\drho{\rho}{XP}{I} = \drho{\rho}{X}{I} = \drho\rho XP$.
117			\item \label{item:state-dependent-distance-isometry-switching} $\drho\rho U{V^\dagger U' V} = \drho{V\rho V\dagg}{VUV\dagg}{U'}$.
118		\end{enumerate}
119	\end{lemma}
120	We'll use \eqref{item:state-dependent-distance-conjugation} and \eqref{item:state-dependent-distance-right-multiplication} to convert proofs of group relations into proofs of approximate relations between operators which try to represent the group.
121	
122	The reader interested in following the $\drho\rho\cdot\cdot$ computations in the rest of the paper may find it useful to find their own proofs of the preceeding facts. For completeness, we provide detailed arguments in the sequel.
123	\begin{proof}~
124	\begin{enumerate}[(a)]
125		\item We complete the square.
126		\begin{align}
127			\drho{\rho}{X}{I}^2 
128			&=
129			\Tr_\rho(X-I)^\dagger(X-I)
130			\\&= \Tr_\rho(2I - X - X^\dagger)
131			\\&= 2 - (\Tr_\rho X + \bar{\Tr_\rho X})
132			\\&= 2 - 2\Re\Tr_\rho X.
133		\end{align}
134		\item In the second equality, we use that the map $\rho \mapsto X^\dagger\rho X$ is trace-preserving.
135		\begin{align}
136			\drho{\rho}{XY}{I}^2
137			&= \Tr (XY - I)\rho (XY - I)^\dagger
138			\\&= \Tr (Y - X^\dagger)\rho (Y - X^\dagger)^\dagger
139			\\&= \drho{\rho}{Y}{X^\dagger}^2.
140		\end{align}
141		\item First, suppose $\rho = \proj \psi$ is pure. Then $\drho{\rho}{Z_1}{Z_3} = \norm{Z_1\ket \psi - Z_3\ket\psi}$ and the triangle inequality for the Hilbert space norm applies. Next, notice that $\drho{\rho}{Z_1}{Z_3}^2$ is linear in $\rho$. 
142	
143		Let $\rho = \sum_i \a_i\proj i$ be a convex combination of pairwise orthogonal pure states. Then we apply linearity and Cauchy-Schwarz:	
144		\begin{align}
145			\drho{\rho}{{Z_1}}{Z_3}^2 
146			&= \sum_i \a_i \drho{\proj i}{Z_1}Z_3^2
147			\\&\leq \sum_i \a_i \left[\drho{\proj i}{Z_1}{Z_2}^2+\drho{\proj i}{Z_2}Z_3^2+2\drho{\proj i}{Z_1}{Z_2}\drho{\proj i}{Z_2}Z_3\right]
148			\\&= \drho{\rho}{{Z_1}}{{Z_2}}^2+\drho{\rho}{{Z_2}}{Z_3}^2
149			+2\sum_i 
150			\sqrt{\a_i\Braket{i|({Z_1}-{Z_2})^\dagger({Z_1}-{Z_2})|i}}
151			\sqrt{\a_i\Braket{i|({Z_2}-Z_3)^\dagger({Z_2}-Z_3)|i}}
152			\\&\leq \drho{\rho}{{Z_1}}{{Z_2}}^2+\drho{\rho}{{Z_2}}{Z_3}^2
153			+2\sqrt{\sum_i \a_i
154			\Braket{i|({Z_1}-{Z_2})^\dagger({Z_1}-{Z_2})|i}
155			\sum_j\a_j
156			\Braket{j|({Z_2}-Z_3)^\dagger({Z_2}-Z_3)|j}}
157			\\&= \drho{\rho}{{Z_1}}{{Z_2}}^2+\drho{\rho}{{Z_2}}{Z_3}^2
158			+2\drho{\rho}{{Z_1}}{{Z_2}}\drho{\rho}{{Z_2}}{Z_3} 
159			\\&= \left(\drho{\rho}{{Z_1}}{{Z_2}} + \drho{\rho}{{Z_2}}{Z_3}\right)^2.
160		\end{align}
161		\item Applying \eqref{item:state-dependent-distance-inverse} and \eqref{item:state-dependent-distance-triangle},
162		\begin{align}
163			\drho{\rho}{XY}{Z}
164			&= \drho{\rho}{XYZ^\dagger}{I}
165			\\&= \drho{\rho}{X}{ZY^\dagger}
166			\\&\leq \drho{\rho}{X}{I} + \drho{\rho}{I}{ ZY^\dagger}
167			\\&= \drho{\rho}{X}{I} + \drho{\rho}{Y}{ Z}.
168		\end{align}
169		If $Y$ commutes with $Z$, then we have
170		\begin{align}
171			\drho{\rho}{XY}{Z}
172			&= \drho{\rho}{XYZ^\dagger}{I}
173			\\&= \drho{\rho}{XZ^\dagger Y}{I}
174			\\&= \drho{\rho}{Y}{ZX^\dagger}
175			\\&\leq \drho{\rho}{Y}{I} + \drho{\rho}{X}{ Z}.
176		\end{align}
177		\item We apply \eqref{item:state-dependent-distance-inverse} and then apply \eqref{item:state-dependent-distance-right-multiplication} once for each $i$.
178		\begin{align}
179			\drho{\rho}{\prod_{i}A_i\otimes I_B}{\prod_{i}I_A\otimes B_i} 
180			&= \drho{\rho}{\prod_{i}A_i\otimes B_i^\dagger}{I}
181			\\&\leq \sum_i \drho{\rho}{A_i\otimes B_i^\dagger}{I}
182			\\&= \sum_i \drho{\rho}{A_i\otimes I_B}{I_A \otimes B_i}.
183		\end{align}
184		\item This follows from \eqref{item:state-dependent-distance-inverse} and \eqref{item:state-dependent-distance-chaining} by writing $I_A \otimes BW = (A)(I_A)(A^\dagger)\otimes (B)(WB)(B^\dagger)$.
185		\item By linearity and \eqref{item:state-dependent-distance-square}, we have
186		\begin{align}
187			\drho{\rho}{\E{i}{U_i}}{I}^2 
188			&= 2 - 2\Re\Tr_\rho\left[\E{i} U_i\right]
189			\\&= \E{i}\left[ 2 - 2\Re\Tr_\rho U_i\right]
190			\\&= \E{i} \drho{\rho}{U_i}{I}^2.
191		\end{align}
192		Then Jensen's inequality completes the proof. 
193		\item We use that the trace of the partial trace is the trace.
194		\begin{align}
195			\drho{\rho}{A\otimes I_B}{I}^2 
196			&= 2 - 2\Re\Tr_\rho A\otimes I_B 
197			\\&= 2 - 2\Re\Tr_{\rho_A}A 
198			\\&= \drho{\rho_A}{A}{I}^2.
199		\end{align}
200		\item We apply cyclicity of trace and unitarity, i.e.\ $V\dagg V = I$. 
201		\begin{align}
202			\drho{V\rho V\dagg}{VZ_1V\dagg}{VZ_2V\dagg}^2
203			&= \Tr V(Z_1-Z_2)\dagg V\dagg V(Z_1-Z_2)V\dagg V\rho V\dagg
204			\\&= \Tr V(Z_1-Z_2)\dagg (Z_1-Z_2)\rho V\dagg
205			\\&= \Tr (Z_1-Z_2)\dagg (Z_1-Z_2)\rho.
206		\end{align}
207		\item Again, we apply cyclicity of trace.
208		\begin{align}
209			\drho\rho{XP}I^2
210			&= \Tr_\rho (XP- I)\dagg(XP-I)
211			\\&= \Tr (PX\dagg- I)(XP-I)\rho
212			\\&= \Tr (PX\dagg- I)(X-I)\rho
213			\\&= \Tr \rho(PX\dagg- I)(X-I)
214			\\&= \Tr_\rho(X\dagg- I)(X-I)
215			\\&= \drho\rho XI^2.
216		\end{align}
217		This gives the first equality; a similar manipulation gives the second.
218		\item By unitary of $U$, we can apply \eqref{item:state-dependent-distance-inverse} to get
219		\begin{equation}
220			\drho\rho U{V\dagg U' V}
221			= \drho\rho {U\dagg V\dagg U' V} I.
222		\end{equation}
223		Next we apply \eqref{item:state-dependent-distance-isometry} to obtain
224		\begin{equation}
225			\drho\rho U{V\dagg U' V}
226			= \drho{V\rho V\dagg} {VU\dagg V\dagg U' V V\dagg} {VV\dagg}.
227		\end{equation}
228		Now we notice that $VV\dagg$ is a projection with $(VV\dagg) V\rho V\dagg = V\rho V\dagg$, so we apply both parts of \eqref{item:state-dependent-distance-projection-is-identity}:
229		\begin{equation}
230			\drho{V\rho V\dagg} {VU\dagg V\dagg U' V V\dagg} {VV\dagg}
231			=\drho{V\rho V\dagg} {VU\dagg V\dagg U'} {I}.
232		\end{equation}
233		Finally, by unitary of $U'$, we can apply \eqref{item:state-dependent-distance-inverse} to get
234		\begin{equation}
235			\drho{V\rho V\dagg} {VU\dagg V\dagg U'} {I}
236			=\drho{V\rho V\dagg} {VU\dagg V\dagg} {(U')\dagg}.
237		\end{equation}
238		Taking adjoints and chaining equalities recovers the desired equation.
239	\end{enumerate}
240	\end{proof}
241	
242	We now use some of the properties of the state-dependent distance to give an approximate version of Lemma \ref{lemma:unitary-observable-strategy-exact} from Section \ref{sec:linear-constraint-games}.
243	
244	\begin{lemma}[Observable form for LCS game strategies, approximate version]\label{lemma:unitary-observable-strategy}
245		Suppose that $\set{A_e^{(v)}}, \set{B_e}, \rho$ is a strategy presented via observables. Let $p_\text{con}$ be the probability that Alice and Bob pass the consistency check, $p_\text{sat}$ be the probability that Alice and Bob pass the constraint satisfaction check, and $p_\text{win}$ be the probability that they pass both checks. Then we have the immediate bounds
246		\begin{equation}
247			p_\text{sat} + p_\text{con} - 1 \leq p_\text{win} \leq \min\set{p_\text{sat}, p_\text{con}},
248		\end{equation}
249		together with the following bounds on $p_\text{sat}$ and $p_\text{con}$ in terms of the strategy:
250		
251		\begin{align}
252			\label{eq:approximate-win-criterion-con}
253			\eta &= \E{v,e} \frac14\drho{\rho}{A_e^{(v)}\otimes B_e}{I}^2,
254			&\eta &\leq 1-p_\text{con} \leq d^2\eta,
255			\\ \label{eq:approximate-win-criterion-sat}
256			\mu &= 
257			\E{v} \frac14
258			\drho{\rho}{\prod_{e}\left(A_e^{(v)}\right)^{H(v,e)}\otimes I}{\w_d^{l(v)}I}^2,
259			&\mu &\leq 1-p_\text{sat} \leq d^2\mu.
260		\end{align}
261	\end{lemma}
262	
263	\begin{proof}[Proof of Lemma \ref{lemma:unitary-observable-strategy}]
264		As in the proof of the exact case, let $\tilde B^i_e$ and $\tilde A_v^a$ be projectors onto the eigenspaces of the observables, as in the following spectral decomposition:
265		\begin{align}
266			B_e:= \sum_j\w_d^{-j}\tilde B^{i}_{e}
267			&& 
268			A_e^{(v)}:= \sum_i \w_d^i\sum_{a: a(e) =i} \tilde A_{v}^a.
269		\end{align}
270	
271		Now, we compute
272		\begin{align}
273			\E{v,e}\Tr_\rho A_e^{(v)}\otimes B_e 
274				&= \E{v,e}\sum_{i,j}\w_d^{i-j}\Tr_\rho \left(\sum_{a: a(e) =i} \tilde A_{v}^a\right)\otimes \tilde B^{j}_{e} 
275			\\	&= \E{v,e}\sum_k \w_d^k\Pr[a(e) - b \equiv k\mid \text{questions }x=v, y=e].
276			\\	&= p_\text{con} + \sum_{k\in \Z_d\minus\set 0} \w_d^k\Pr[a(e) - b \equiv k].
277		\end{align}
278		Taking real parts and applying the inequalities of complex numbers \ref{lemma:convex-inequality-easy}, \ref{lemma:convex-inequality-hard}, we recover equation \eqref{eq:approximate-win-criterion-con}:
279		\begin{align}
280			1 - 2 (1 - p_\text{con})
281			\leq
282			&\E{v,e} \Re\Tr_\rho A_e^{(v)}\otimes B_e
283			\leq 
284			1 - 2d^{-2}(1-p)
285			\\
286			4 (1-p_\text{con})
287			\geq
288			&\E{v,e} \drho{\rho}{A_e^{(v)}\otimes B_e}{I}^2
289			\geq 
290			4 d^{-2}(1-p_\text{con}).
291		\end{align}
292		(To get from the first line to the second, we applied Lemma \ref{lemma:state-dependent-distance}\eqref{item:state-dependent-distance-square}.)
293		
294	
295		With a similar computation, we get:
296		\begin{align}
297			 &\E{v}\w_d^{-l(v)}\Braket {\psi |\prod_{e} \left(A_e^{(v)}\right)^{H(v,e)}\otimes I | \psi } \\
298			= & \E{v}\sum_k\w_d^{k}\Braket {\psi |\sum_{\substack{a\\ \sum_e H(v,e)a(e)\equiv k}} \tilde A_{v}^a\otimes I |\psi} \\
299			= & \E{v}\sum_k \w_d^{k-l(v)}\Pr\left[\sum_{e}H(v,e)a(e)\equiv k\middle| \text{ question }x=v\right]\\
300			= & p_\text{sat} + \sum_{k\in \Z_d\minus\set 0} \w_d^k\Pr\left[\sum_{e}H(v,e)a(e)\equiv k+l(v)\right].
301		\end{align}
302		Again, \eqref{eq:approximate-win-criterion-sat} follows from the above via Lemmas \ref{lemma:convex-inequality-easy} and \ref{lemma:convex-inequality-hard}.
303	\end{proof}
304	
305	\subsection{The stability lemma}
306	\label{subsection:stability-lemma}
307	% We'll be sloppy in our analysis, aiming only to achieve a robustness bound scaling as some polynomial in $p$. We expect that a more abstract approach will be able to find optimal scaling for a broader class of groups; we leave this to future work. 
308	
309	We'll use a general stability theorem for approximate representations of finite groups, which will let us take the following approach to robustness. From a quantum strategy winning with high probability, we extract an ``approximate representation'' of the solution group, i.e.\ a map from the group to unitaries which is approximately a homomorphism. The stability theorem lets us conclude that this function is close to an exact representation in the way that the unitaries act on the joint state of the provers, up to a local isometry. Once we have a representation, we'll be able to start applying reasoning analagous to that of \S \ref{subsection:exact-self-testing}. 
310	
311	We were first made aware of results of this type by \cite{gowers2015inverse}. The result of interest was restated more conveniently in \cite{gowers2017generalizations}. In what follows, $U(\m H)$ will denote the group of unitary operators on the Hilbert space $\m H$. 
312	\begin{thm}[Informal statement of Theorem 15.2 of \cite{gowers2017generalizations}]\label{thm:gowers-hatami}
313		Let $G$ be a finite group and $f: G\to U(\C^n)$ be such that $\norm{f(x)f(y) - f(xy)}_2 \leq \e\sqrt n$ for all $x,y\in G$. Then there exists $m \leq (1+\e^2)n$, an isometry $V: \C^n\to C^m$, and a unitary representation $\s : G \to U(\C^m)$, such that $\norm{f(x) - V^\dagger\s(x)V}_2 \in O(\e\sqrt n)$ for every $x\in G$.
314	\end{thm}
315	
316	Applying this theorem directly requires a guarantee on the Hilbert-Schmidt distance between operators. However, experiments with nonlocal games will only give us guarantees on the state-dependent distance $D_\rho$ between operators, where $\rho$ is the state used by the provers. The following variant addresses this concern. The statement and proof are due to Vidick.
317	\begin{lemma}[\cite{vidick2017approx}]\label{lemma:vidick-gowers-hatami}
318		Let $G$ be a finite group, $f: G \to U(\m H_A)$ be such that $f(x\1) = f(x)^\dagger$, $\rho_{AB}$ a state on $\m H_A\otimes \m H_B$  and
319		\begin{equation}
320			\E{x,y\in G}\drho\rho{f(x)f(yx)^\dagger f(y)\otimes I_B}{I_{AB}} \leq \eta.
321		\end{equation}
322		Then there is some Hilbert space $\m H_{\hat A}$, an isometry $V: \m H_A\to \m H_{\hat A}$, and a representation $\tau: G\to U(\m H_{\hat A})$ such that
323		\begin{align}
324			\E{x\in G} \drho{\rho}{f(x)\otimes I_B}{ V^\dagger \tau(x)V\otimes I_B} 
325			&\leq \eta\text{, or equivalently}
326			\E{x\in G} \drho{(V\otimes I_B)\rho (V\otimes I_B)\dagg}{Vf(x)V\dagg\otimes I_B}{\tau(x)\otimes I_B} 
327			&\leq \eta.
328		\end{align}
329	\end{lemma}
330	
331	\noindent
332	Notice the lack of a dimension bound on $\hat A$. From the proof one can check that the dimension of $\hat A$ is at most $\abs G^2$ times the dimension of $A$. We won't use any dimension bound explicitly, and proving a tight dimension bound takes considerable effort. 
333	We give a self-contained proof of Lemma \ref{lemma:vidick-gowers-hatami}. 
334	
335	\begin{proof}[Proof of Lemma \ref{lemma:vidick-gowers-hatami}, \cite{vidick2017approx}]
336		Let $\s$ vary over irreducible representations of $G$. For each $\s$, let $n_\s$ be the dimension of $\s$.
337		We define a generalized Fourier transform of $f$, which acts on irreps of $G$, by 
338		\begin{equation}
339			\hat f(\s) = \E{x\in G} f(x) \otimes \bar {\s (x)} \in \m L(C^d\otimes \C^{n_\s}).
340		\end{equation}
341		Let $\m H_{A_1A_2} = \bigoplus_\s \C^{n_\s}_{A_1}\otimes \C^{n_\s}_{A_2}$. (Notice that the dimension of $\m H_{A_1A_2}$ is $\abs G$ by Fact \ref{fact:character-dimension}.) For each $\s$, define a state $\ket{\r{EPR}_\s} = \frac1{\sqrt {n_\s}}\sum_i^{n_\s}\ket{ii}$ in the $\s$-summand of $\m H_{A_1A_2}$. (Notice that the $\ket{\r{EPR}_\s}$ form an orthonormal family.)
342		Let $\m H_{A_3} = \Span\set{\ket \s}$ be a Hilbert space of dimension equal to the number of inequivalent irreps of $G$. Finally, we define the Hilbert space $\m H_{\hat A}$, isometry $V: \m H_A \to \m H_{\hat A}$, and representation $\tau: G\to U(\m H_{\hat A})$ from the statement of the lemma. 
343		\begin{align}
344			{\m H}_{\hat A} &= {\m H}_A\otimes {\m H}_{A_1}\otimes {\m H}_{A_2}\otimes {\m H}_{A_3},
345			\\V &= \sum_\s n_\s(\hat f(\s)_{AA_1}\otimes I_{A_2})(I_A\otimes \ket\eprrho_{A_1A_2}\otimes \ket\s_{A_3}),
346			\\\tau(x) &= I_{AA_1} \otimes \sum_\s (\s(x)_{A_2} \otimes \proj \s_{A_3}).
347		\end{align}
348		It's clear that $\tau$ is a unitary representation. We check that $V$ is an isometry:
349		\begin{align}
350			V^\dagger V 
351			&= \sum_\s n_{\s}^2(I_A \otimes \bra\eprrho)\hat f (\s)^\dagger \hat f(\s)(I_A\otimes \ket\eprrho)
352			\\&= \sum_\s n_{\s} \Tr_{A_1}\hat f (\s)^\dagger \hat f(\s)
353			\\&= \b E_x f (x)^\dagger  f(x) 
354			\\&= I_A.
355		\end{align}
356		Now we compute the pullback of $\tau$ along $V$:
357		\begin{align}
358			V^\dagger \tau(x) V 
359			&= \sum_\s n_{\s}^2(I_A \otimes \bra\eprrho) (\hat f (\s)^\dagger \hat f(\s) \otimes \s(x))(I_A\otimes \ket\eprrho)
360			\\&= \sum_\s n_{\s}^2 \b E_{y,z\in G}f(y)^\dagger f(z)\bra\eprrho\s(y)^T\bar{\s(z)} \otimes \s(x) \ket\eprrho
361			\\&= \sum_\s n_{\s}  \b E_{y,z\in G} \Tr(\s(x)^T\s(y)^T\bar{\s(z)})f(y)^\dagger f(z)
362			\\&= \b E_{y\in G}\sum_\s n_{\s}   \b E_{z\in G}\Tr(\s(yxz\1))f(y)^\dagger f(z)
363			\\&= \b E_{y\in G} f(y)^\dagger f(yx),
364		\end{align}
365		where the last equality follows from Fact \ref{fact:orthogonality}. 
366		
367		Then it follows from properties of $\drho\rho\cdot\cdot$ that
368		\begin{align}
369			\E{x\in G} \drho{\rho}{f(x)\otimes I_B}{ V^\dagger \tau(x) V\otimes I_B}
370			&=
371			\E{x,y\in G} \drho{\rho}{f(x)f(yx)^\dagger f(y)\otimes I_B}{I} 
372			\\&\leq \eta.
373		\end{align}
374		The equivalence of the two forms of the conclusion follows from Lemma \ref{lemma:state-dependent-distance}\eqref{item:state-dependent-distance-isometry-switching}.
375	\end{proof}
376	\noindent Notice that we can also use the lemma with the isometry acting on the state instead of the representation, since
377		\begin{align}
378			\E{x\in G} \drho{\rho}{f(x)\otimes I_B}{V^\dagger \tau(x) V\otimes I_B}
379			&=\E{x\in G} \drho{\rho}{f(x)V^\dagger \tau(x)^\dagger V\otimes I_B}{ I}
380			\\&=\E{x\in G} \drho{V\rho V^\dagger}{Vf(x)V^\dagger \tau(x)^\dagger VV^\dagger\otimes I_B}{I}

