164	 	Then
165	 	\begin{enumerate}
166	 		\item\label{item:prop-four-edges-1} $[x_1,z_1] = J = [x_2,z_2]$, and
167	 	 	\item\label{item:prop-four-edges-2} $\set{x_1,x_2,z_1,z_2, J}$ generates $\G_2$.
168	 	\end{enumerate}
169	 \end{lemma} 
